-- Isolated fixtures and all writes roll back. Never creates public demo scores/posts.
begin;
do $$declare u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();r jsonb;r2 jsonb;ans integer[];idea uuid;result jsonb;begin
 if has_table_privilege('authenticated','shams_private.quiz_credits','INSERT') or has_table_privilege('anon','shams_private.ideas','SELECT') or has_function_privilege('anon','public.shams_idea_post(text,text)','EXECUTE') then raise exception 'Unsafe grants';end if;
 insert into auth.users(id,email,raw_user_meta_data) values(u,u||'@example.invalid','{"display_name":"Rollback test"}'),(v,v||'@example.invalid','{"display_name":"Rollback other"}');
 perform set_config('request.jwt.claim.sub',u::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 perform public.shams_leader_join('Rollback test',true);
 update shams_private.module_policy set mode='closed' where module='quiz';
 begin perform public.shams_quiz_start('quran',1);raise exception 'Closed quiz allowed';exception when raise_exception then if sqlerrm<>'Quiz unavailable' then raise;end if;end;
 update shams_private.module_policy set mode='free' where module='quiz';
 idea:=public.shams_idea_post('Rollback test idea','This test is rolled back and never published.');
 begin perform public.shams_idea_admin(idea,'No','completed',false);raise exception 'Non-admin wrote reply';exception when raise_exception then if sqlerrm<>'Admin required' then raise;end if;end;
 r:=public.shams_quiz_start('quran',1);
 select array_agg(b.correct order by t.n) into ans from jsonb_array_elements_text(r->'questions') with ordinality t(id,n) join shams_private.quiz_bank b on b.id=t.id;
 result:=public.shams_quiz_finish((r->>'id')::uuid,ans);
 if (result->>'awarded')::integer<>100 then raise exception 'Correct answers not scored';end if;
 result:=public.shams_quiz_finish((r->>'id')::uuid,ans);
 if result->>'replayed'<>'true' or (select sum(points) from shams_private.quiz_credits where user_id=u)<>100 then raise exception 'Round replay credited twice';end if;
 r2:=public.shams_quiz_start('quran',1);
 begin perform public.shams_quiz_finish((r2->>'id')::uuid,null);raise exception 'Null answers accepted';exception when raise_exception then if sqlerrm<>'Invalid or expired round' then raise;end if;end;
 select array_agg(b.correct order by t.n) into ans from jsonb_array_elements_text(r2->'questions') with ordinality t(id,n) join shams_private.quiz_bank b on b.id=t.id;
 result:=public.shams_quiz_finish((r2->>'id')::uuid,ans);
 if (result->>'awarded')::integer<>0 then raise exception 'Repeated question credited twice in one day';end if;
 perform set_config('request.jwt.claim.sub',v::text,true);
 begin perform public.shams_quiz_finish((r->>'id')::uuid,ans);raise exception 'Other user round accepted';exception when raise_exception then if sqlerrm<>'Round not found' then raise;end if;end;
 if public.shams_quiz_start('quran',1) is not null then raise exception 'Non-member ranked';end if;
 update shams_private.ideas set hidden=true where id=idea;
 if exists(select 1 from jsonb_array_elements(public.shams_ideas_list(300,true)) p where p->>'id'=idea::text) then raise exception 'Hidden idea leaked to user';end if;
 perform set_config('request.jwt.claim.sub',u::text,true);
 perform public.shams_leader_join('Rollback test',false);
 if exists(select 1 from jsonb_array_elements(public.shams_leaderboard()->'rows') p where p->>'user_id'=u::text) then raise exception 'Opt-out leaked';end if;
 update public.shams_profiles set disabled=true where id=u;
 begin perform public.shams_idea_post('Disabled test','No posting allowed');raise exception 'Disabled user posted';exception when raise_exception then if sqlerrm<>'Sign in required' then raise;end if;end;
end$$;
rollback;
select 'PASS: private grants, server answers, replay, daily credits, ownership, opt-in, hidden posts, admin-only reply and blocked account; fixtures rolled back' as result;
